// ── Normaliza payload e RETORNA CADA SEGMENTO COMO UM ITEM SEPARADO NO N8N ──
const body = $input.item.json.body || $input.item.json;
const tpl  = body.template || {};

const sessionId    = `dt_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
const captionStyle = tpl.caption_style || 'pop';
const animationMix = tpl.animation_mix || 'varied';
const language     = (tpl.language || 'pt').toLowerCase();
const format       = tpl.format       || 'vertical';

// ── Seleção Inteligente de Voz e TTS Engine ──
// Piper Local (OpenedAI Speech): Latência ultrabaixa (<200ms), GPU local, zero custo, vozes PT e EN
// Edge-TTS Cloud: Fallback automático para 80+ outros idiomas (es, fr, de, it, ja, etc.)
function resolveVoiceAndEngine(rawVoice, lang, emotion) {
  const normLang = lang.startsWith('pt') ? 'pt' : (lang.startsWith('en') ? 'en' : lang);
  const emo = String(emotion || '').toLowerCase();

  if (normLang === 'pt') {
    // Mapeamento emocional Piper PT-BR
    let voice = 'faber'; // Padrão de altíssima qualidade
    if (['dark', 'suspense', 'terror', 'grave', 'misterio', 'impacto', 'serio'].some(e => emo.includes(e))) {
      voice = 'jeff'; // Voz grave/dark
    } else if (['jovem', 'energetico', 'alegria', 'viral', 'hype', 'humor', 'curiosidade'].some(e => emo.includes(e))) {
      voice = 'cadu'; // Voz jovem/dinâmica
    } else if (['portugal', 'pt-pt', 'europeu'].some(e => emo.includes(e) || lang.includes('pt-pt'))) {
      voice = 'tugao'; // Voz pt-PT
    }

    // Se o usuário especificou explicitamente uma voz conhecida
    if (rawVoice) {
      const rv = String(rawVoice).toLowerCase();
      if (['faber', 'cadu', 'jeff', 'edresson', 'tugao'].includes(rv)) voice = rv;
    }
    return {
      engine: 'piper',
      voice,
      url: 'http://n8n-piper-yhoamw:8000/v1/audio/speech'
    };
  }

  if (normLang === 'en') {
    let voice = 'onyx'; // Padrão profundo
    if (['energetic', 'fast', 'viral', 'young'].some(e => emo.includes(e))) {
      voice = 'nova';
    } else if (['calm', 'soft', 'story'].some(e => emo.includes(e))) {
      voice = 'alloy';
    }
    if (rawVoice && ['alloy', 'echo', 'fable', 'onyx', 'nova', 'shimmer'].includes(String(rawVoice).toLowerCase())) {
      voice = String(rawVoice).toLowerCase();
    }
    return {
      engine: 'piper',
      voice,
      url: 'http://n8n-piper-yhoamw:8000/v1/audio/speech'
    };
  }

  // Multilingual Fallback: Edge-TTS
  const edgeFallback = lang.startsWith('es') ? 'es-ES-AlvaroNeural' :
                       lang.startsWith('fr') ? 'fr-FR-HenriNeural' :
                       lang.startsWith('de') ? 'de-DE-ConradNeural' :
                       lang.startsWith('it') ? 'it-IT-DiegoNeural' :
                       'en-US-ChristopherNeural';
  return {
    engine: 'edge-tts',
    voice: rawVoice || edgeFallback,
    url: 'https://edge-tts.fjt-solutions.com/v1/audio/speech'
  };
}

const rawSegments = tpl.script_segments || body.script_segments || [];
let segments = rawSegments.length > 0 ? rawSegments : [{
  index: 0,
  voiceover: { text: tpl.video_title || 'Vídeo sem narração' },
  visual_content: { image_prompt: tpl.video_title || 'Cena principal' },
  emotion: 'neutral'
}];

const userMedia = tpl.user_media || tpl.uploaded_images || tpl.images || [];
const hasUserMedia = Array.isArray(userMedia) && userMedia.length > 0;
if (hasUserMedia && userMedia.length < segments.length) {
  segments = segments.slice(0, userMedia.length);
}

return segments.map((seg, idx) => {
  const sceneEmotion = seg.emotion || tpl.emotion || 'neutral';
  const ttsInfo = resolveVoiceAndEngine(tpl.voice || body.voice, language, sceneEmotion);
  return {
    json: {
      ...seg,
      index: seg.index !== undefined ? seg.index : idx,
      session_id:     sessionId,
      render_engine:  'pending_ai_selection',
      caption_style:  captionStyle,
      animation_mix:  animationMix,
      language,
      voice:          ttsInfo.voice,
      tts_engine:     ttsInfo.engine,
      tts_url:        ttsInfo.url,
      format,
      has_music:      tpl.has_music      || false,
      primary_color:  tpl.primary_color  || '#EAB308',
      accent_color:   tpl.accent_color   || '#FFFFFF',
      watermark_text: tpl.watermark_text || 'DarkTube AI',
      topic:          tpl.video_title    || '',
      emotion:        sceneEmotion,
      user_media:     userMedia,
      tpl
    }
  };
});

// Seleciona Imagem da Cena - estritamente 1-para-1 com a imagem enviada
const norm        = $json;
const idx         = parseInt(norm.index !== undefined ? norm.index : 0);
const tpl         = norm.tpl || {};
const visual      = norm.visual_content || {};

const userMedia   = norm.user_media || tpl.user_media || tpl.uploaded_images || tpl.images || [];

let providedUrl = norm.image_url
  || norm.media_url
  || visual.image_url
  || (Array.isArray(userMedia) && userMedia[idx] ? (userMedia[idx].file_url || userMedia[idx]) : '')
  || '';

let imageUrl = providedUrl || tpl.video_thumbnail || '';
let source   = providedUrl ? 'user_uploaded_image' : 'template_thumbnail';

// Converter paths relativos para URLs absolutas
const DARKTUBE_BASE = 'https://darktube.fjt-solutions.com';
if (imageUrl && !imageUrl.startsWith('http://') && !imageUrl.startsWith('https://') && !imageUrl.startsWith('data:')) {
  imageUrl = DARKTUBE_BASE + (imageUrl.startsWith('/') ? '' : '/') + imageUrl;
}

return [{ json: { ...norm, image_url: imageUrl, source } }];

// ── Monta SceneSegment completo (v7 — SFX Cues + Piper TTS + Whisper) ──
const segment = $('Generate Scene Image').item.json;
const idx     = parseInt(segment.index !== undefined ? segment.index : 0);

// ── Whisper vem de Whisper Word Timestamps (branch paralelo) ──
let wRes = {};
try { wRes = $('Whisper Word Timestamps').item.json; } catch (_) {}

const voiceover = segment.voiceover || {};
const visual    = segment.visual_content || {};

// ── IMAGEM ──
const imageUrl = segment.image_url || segment.media_url || visual.image_url || segment.tpl?.video_thumbnail || '';

// ── ÁUDIO — URL pública gerada pelo nó Upload TTS Audio (branch paralelo) ──
let audioUrl = '';
try {
  const uploadResult = $('Upload TTS Audio').item.json;
  audioUrl = uploadResult.url || uploadResult.publicUrl || '';
} catch (err) {
  const text2 = voiceover.text || segment.voiceover_text || segment.text || '';
  const voice2 = segment.voice || 'faber';
  if (text2) {
    try {
      const r = await fetch(segment.tts_url || 'http://n8n-piper-yhoamw:8000/v1/audio/speech', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: 'tts-1', input: text2, voice: voice2, speed: 1.0, response_format: 'mp3' })
      });
      if (r.ok) {
        const ab = await r.arrayBuffer();
        audioUrl = `data:audio/mp3;base64,${Buffer.from(ab).toString('base64')}`;
      }
    } catch (_) {}
  }
}

// ── LEGENDA ──
const text = voiceover.text || segment.voiceover_text || segment.voiceoverText || segment.text || '';
const captionText = text;

// ── PALAVRAS (timestamps do Whisper) ──
const rawWords = (wRes.words || wRes.segments?.[0]?.words || []);
const MIN_WORD_DISPLAY = 0.35;
const words = rawWords.map((w, wi) => {
  const start = parseFloat(w.start);
  const rawEnd = parseFloat(w.end);
  const nextStart = (wi < rawWords.length - 1) ? parseFloat(rawWords[wi + 1].start) : rawEnd + 1;
  const expandedEnd = Math.max(rawEnd, start + MIN_WORD_DISPLAY, Math.min(start + 0.8, nextStart - 0.02));
  return { word: w.word, startInSeconds: start, endInSeconds: expandedEnd };
});

// ── DURAÇÃO ──
const audioDuration = wRes.duration || 5;
const duration = audioDuration + 2;

// ── ANIMAÇÃO ──
const ALL_STYLES = ['zoom-punch','tilt-3d','parallax-up','parallax-down','zoom-out','shake-impact','spin-in','kenburns-right','kenburns-left'];
let animationStyle;
if (segment.animation_mix === 'kenburns')        animationStyle = idx % 2 === 0 ? 'kenburns-right' : 'kenburns-left';
else if (segment.animation_mix === 'zoom-punch') animationStyle = 'zoom-punch';
else animationStyle = ALL_STYLES[idx % ALL_STYLES.length];

return [{
  json: {
    index: idx,
    imageUrl,
    audioUrl,
    captionText,
    words,
    durationSeconds: duration,
    animationStyle,
    transitionIn: 'fade',
    sfxOnEnter: idx === 0 ? 'whoosh-heavy' : 'whoosh',
    sfxOnData: 'none',
    emotion: segment.emotion || 'neutral'
  }
}];

